window.INVITATION_TEMPLATE = "\u003c!doctype html>\n\u003chtml lang=\"de\">\n\u003chead>\n  \u003cmeta charset=\"utf-8\">\n  \u003cmeta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n  \u003cmeta name=\"theme-color\" content=\"#f6f3ed\">\n  \u003cmeta name=\"description\" content=\"Marie und Simon heiraten. Eine gestickte Einladung mit unserer Kirche, Lieblingsmenschen und einer Feier im Mago.\">\n  \u003ctitle>Marie &amp; Simon · Wir heiraten\u003c/title>\n  \u003clink rel=\"icon\" href=\"data:image/svg+xml;base64,\" type=\"image/svg+xml\">\n\n  \u003cstyle>@font-face{font-family:Cormorant;src:url('data:font/woff2;base64,') format('woff2');font-weight:400;font-display:swap}\n@font-face{font-family:Cormorant;src:url('data:font/woff2;base64,') format('woff2');font-weight:500;font-display:swap}\n@font-face{font-family:Cormorant;src:url('data:font/woff2;base64,') format('woff2');font-style:italic;font-display:swap}\n@font-face{font-family:Manrope;src:url('data:font/woff2;base64,') format('woff2');font-weight:400;font-display:swap}\n@font-face{font-family:Manrope;src:url('data:font/woff2;base64,') format('woff2');font-weight:500;font-display:swap}\n:root{--paper:#f6f3ed;--ink:#4b5852;--muted:#59665c;--rose:#80566a;--gold:#b29b74;--line:#d1d2c6;--serif:Cormorant,Georgia,serif;--sans:Manrope,Arial,sans-serif;--script:Cormorant,Georgia,serif}\n*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:80px}body{margin:0;background:var(--paper) url('data:image/webp;base64,') repeat;background-size:560px 560px;color:var(--ink);font:clamp(1.125rem, 2.4vw, 1.3125rem)/1.55 var(--serif);-webkit-font-smoothing:antialiased}button,input,textarea{font:inherit;color:inherit}button,a{-webkit-tap-highlight-color:transparent}button{cursor:pointer}a{color:inherit;text-decoration:none}img{display:block;max-width:100%;height:auto}[hidden]{display:none!important}h1,h2,h3,p,figure{margin:0}h1,h2,h3{font-family:var(--serif);font-weight:400;line-height:1.12;text-wrap:balance}h2{font-size:clamp(2.15rem, 5.7cqw, 3.25rem);letter-spacing:-.018em}h3{font-size:33px}p{white-space:pre-line}em{font-weight:400}button:focus-visible,a:focus-visible,summary:focus-visible,input:focus-visible,textarea:focus-visible{outline:2px solid var(--rose);outline-offset:5px}.skip-link{position:fixed;left:20px;top:-100px;z-index:100;background:var(--ink);color:var(--paper);padding:12px}.skip-link:focus{top:12px}.invitation-sheet{max-width:880px;margin:auto;container-type:inline-size}main,footer{width:100%;margin:auto}.text-button{display:inline-flex;align-items:center;gap:15px;border:0;border-bottom:1px solid #bfc5b8;background:none;padding:9px 0;font:11px/1.5 var(--sans);letter-spacing:.8px}.primary-button{background:var(--ink);color:var(--paper);border:1px solid var(--ink);display:inline-flex;align-items:center;justify-content:center;gap:30px;padding:15px 30px;min-width:235px;font:11px/1.6 var(--sans);letter-spacing:1px;transition:background .2s}.primary-button:hover{background:#687968}.text-button>span,.nav-rsvp>span,.primary-button>span{font-size:0;width:14px;height:14px;position:relative;display:inline-block;flex:0 0 14px}.text-button>span:before,.nav-rsvp>span:before,.primary-button>span:before{content:\"\";position:absolute;left:1px;bottom:2px;width:15px;height:1px;background:currentColor;transform:rotate(-45deg);transform-origin:left center}.text-button>span:after,.nav-rsvp>span:after,.primary-button>span:after{content:\"\";position:absolute;right:1px;top:2px;width:6px;height:6px;border-top:1px solid currentColor;border-right:1px solid currentColor}\n/* Each illustration has one place in the invitation; all artwork keeps its proportions. */\n.hero{position:relative;width:100%;margin:auto;padding-bottom:55px;text-align:center;background:transparent}.hero-art{display:block;aspect-ratio:2/3}.garden-frame{width:100%;height:100%;object-fit:contain}.hero-copy{position:absolute;top:12%;left:23%;width:54%;z-index:2}.hero h1{display:flex;flex-direction:column;gap:0;font:62px/1.04 var(--serif);letter-spacing:-.5px}.hero h1 em{font:42px/1 var(--serif);margin:7px 0}.hero-date{font-size:21px;letter-spacing:1.5px;margin-top:24px}.hero-place{font:8px var(--sans);letter-spacing:2px;text-transform:uppercase;margin-top:12px}.hero-discover{position:absolute;bottom:5px;left:0;right:0;display:flex;flex-direction:column;gap:5px;align-items:center;font:8px var(--sans);letter-spacing:.5px}.hero-discover span{font-size:20px}.opening-running .hero-copy{animation:soft-arrive 1.6s ease both}.site-header{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 35px;border:0;background:transparent}.brand{font:24px var(--serif)}.site-header nav{display:flex;gap:27px;font:9px var(--sans);letter-spacing:.5px}.nav-rsvp{border:0;border-bottom:1px solid var(--line);background:none;padding:8px 0;display:flex;align-items:center;gap:13px;font:9px var(--sans)}\n/* One linen surface, with spacing sized to the content of each scene. */\n.eyebrow {\n  font: 500 .7rem/1.5 var(--sans);\n  letter-spacing: .16em;\n  text-transform: uppercase;\n}\n\n.section-pad {\n  padding: clamp(3.25rem, 8cqw, 5.25rem) clamp(1.25rem, 6cqw, 3.75rem);\n}\n\n.hero-discover {\n  left: 50%;\n  right: auto;\n  width: max-content;\n  min-height: 44px;\n  padding: 4px 14px;\n  transform: translateX(-50%);\n  font: 500 .75rem/1.4 var(--sans);\n}\n\n.hero-place {\n  font-size: .625rem;\n}\n\n#hero-title:focus {\n  outline: none;\n}\n\n.site-header {\n  gap: 12px 24px;\n  padding: 14px clamp(20px, 5cqw, 45px);\n}\n\n.site-header nav {\n  display: flex;\n  align-items: center;\n  flex-wrap: wrap;\n  justify-content: center;\n  gap: 0 clamp(12px, 3cqw, 27px);\n}\n\n.site-header nav a, .nav-rsvp, .footer-replay {\n  display: inline-flex;\n  align-items: center;\n  min-height: 44px;\n  font: 500 .75rem/1.4 var(--sans);\n  letter-spacing: 0;\n}\n\n.text-button { min-height: 44px; font-size: .75rem; letter-spacing: .015em; }\n.primary-button { min-height: 48px; font-size: .8125rem; letter-spacing: .025em; }\n\n.welcome {\n  position: relative;\n  isolation: isolate;\n  width: 100%;\n  margin-top: clamp(1.5rem, 6cqw, 3.25rem);\n  padding: min(47cqw, 18.5rem) 15% 0;\n  text-align: center;\n}\n\n.welcome .panel-art {\n  position: absolute;\n  inset: 0 0 auto;\n  width: min(100%, 39rem);\n  height: auto;\n  margin-inline: auto;\n  pointer-events: none;\n  z-index: -1;\n}\n\n.welcome-copy {\n  max-width: 26rem;\n  margin-inline: auto;\n}\n\n.welcome-copy h2 {\n  font-size: clamp(1.8rem, 5.5cqw, 3.15rem);\n  white-space: pre-line;\n}\n\n.welcome-copy > p {\n  font-size: clamp(1.0625rem, 2.6cqw, 1.375rem);\n  font-weight: 500;\n  line-height: 1.46;\n  margin-top: 1rem;\n}\n\n.signature {\n  display: block;\n  margin-top: 1rem;\n  font-size: clamp(1.25rem, 3.5cqw, 1.75rem);\n  font-style: italic;\n}\n\n.date-section, .venues-intro, .gift-section, .rsvp-section {\n  text-align: center;\n}\n\n.date-section {\n  padding-top: clamp(3rem, 8cqw, 5.25rem);\n  padding-bottom: clamp(2.5rem, 6cqw, 4rem);\n}\n\n.date-section h2 { margin-top: 9px; }\n\n.date-display {\n  display: flex;\n  flex-direction: column;\n  gap: 4px;\n  margin: .75rem auto 1.25rem;\n}\n\n.date-display > strong { font: clamp(1.625rem, 4cqw, 2rem) var(--serif); }\n.date-display > span { font: 500 .75rem var(--sans); }\n\n.countdown {\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  gap: clamp(4px, 2.5cqw, 20px);\n  margin: 1.25rem auto;\n}\n\n.countdown > div {\n  position: relative;\n  isolation: isolate;\n  width: clamp(5rem, 26cqw, 9rem);\n  aspect-ratio: 1;\n  display: flex;\n  flex-direction: column;\n  align-items: center;\n  justify-content: center;\n}\n\n.countdown img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: contain; z-index: -1; }\n.countdown strong { font: clamp(2.125rem, 7cqw, 3.5rem)/1 var(--serif); }\n.countdown span { margin-top: 4px; font: 500 clamp(.5625rem, 1.7cqw, .6875rem) var(--sans); }\n.countdown-note { margin-top: 12px; color: var(--muted); font-style: italic; }\n\n.section-ornament {\n  width: clamp(9rem, 33cqw, 14rem);\n  height: auto;\n  aspect-ratio: 3/1;\n  object-fit: contain;\n  margin: 0 auto 1.1rem;\n}\n\n.section-note {\n  margin-top: .6rem;\n  color: var(--muted);\n  font: 500 .75rem/1.5 var(--sans);\n}\n\n.venues { padding-top: 0; }\n.venue-grid {\n  display: grid;\n  grid-template-columns: repeat(2, minmax(0, 1fr));\n  gap: clamp(1.25rem, 6cqw, 3.75rem);\n  margin-top: 1.5rem;\n}\n\n.venue-card { text-align: center; }\n.venue-art {\n  position: relative;\n  height: clamp(13rem, 40cqw, 19rem);\n  display: grid;\n  grid-template: minmax(0, 1fr) / minmax(0, 1fr);\n  place-items: center;\n}\n\n.venue-art > [data-photo], .venue-fallback {\n  width: 100%;\n  height: 100%;\n  object-fit: contain;\n  min-height: 0;\n  min-width: 0;\n}\n\n.venue-info h3 { margin-top: .5rem; font-size: clamp(1.75rem, 4cqw, 2.125rem); }\n.venue-time { font-size: 1.625rem; line-height: 1.25; margin-top: .7rem; }\n.venue-arrival, .venue-address { font: 500 .75rem/1.55 var(--sans); color: var(--muted); }\n.venue-arrival { margin-top: .35rem; }\n.venue-description { max-width: 34ch; margin: .8rem auto; color: var(--muted); }\n.venue-address { margin-top: .75rem; }\n\n.story {\n  display: grid;\n  grid-template-columns: minmax(0, .85fr) minmax(0, 1.15fr);\n  align-items: center;\n  gap: clamp(1.75rem, 5cqw, 3.5rem);\n}\n\n.story-copy > p { margin-top: 1rem; color: var(--muted); }\n\n.photo-duo {\n  display: grid;\n  grid-template-columns: minmax(0, 1.7fr) minmax(0, 1fr);\n  align-items: center;\n  gap: clamp(.6rem, 1.7cqw, 1.25rem);\n  padding: 0 .3rem .85rem;\n}\n\n.photo-frame {\n  padding: clamp(5px, 1.1cqw, 10px) clamp(5px, 1.1cqw, 10px) 0;\n  background: #fffcf7;\n  border: 1px solid #c9c6b5;\n  box-shadow: 0 8px 20px #48514419;\n}\n\n.photo-main { transform: rotate(-2deg); }\n.photo-detail { transform: translateY(12px) rotate(3deg); }\n\n.photo-frame > [data-photo] {\n  width: 100%;\n  aspect-ratio: 4 / 5;\n  object-fit: cover;\n  cursor: zoom-in;\n}\n\n.photo-main > [data-photo] { aspect-ratio: 1 / 1; object-position: center 45%; }\n.photo-frame figcaption {\n  padding: .5rem .125rem;\n  font: italic clamp(.875rem, 2.5cqw, 1.0625rem)/1.2 var(--serif);\n  text-align: center;\n}\n\n.photo-fallback {\n  aspect-ratio: 4 / 5;\n  display: grid;\n  place-content: center;\n  justify-items: center;\n  gap: 8px;\n  background: #e9ecdf;\n  text-align: center;\n}\n\n.photo-main .photo-fallback { aspect-ratio: 1; }\n.photo-fallback img { width: min(50%, 100px); }\n.photo-fallback small { font: .75rem var(--sans); }\n.fallback-amp { font-size: 2rem; font-style: italic; }\n\n.story-quote {\n  grid-column: 1 / -1;\n  text-align: center;\n  font: italic clamp(1.75rem, 5cqw, 2.625rem)/1.2 var(--serif);\n}\n\n.timeline-header { text-align: center; margin-bottom: 1.75rem; }\n.timeline-header h2 { margin-top: .4rem; }\n.timeline {\n  --icon-width: clamp(3.75rem, 16cqw, 5.25rem);\n  --timeline-gap: clamp(1.75rem, 7cqw, 2.75rem);\n  --thread-x: calc(var(--icon-width) + var(--timeline-gap) / 2);\n  position: relative;\n  list-style: none;\n  max-width: 33rem;\n  padding: 0;\n  margin: 0 auto;\n}\n\n/* The same running stitch joins every stop. */\n.timeline::before {\n  content: \"\";\n  position: absolute;\n  inset: 1.5rem auto 2rem var(--thread-x);\n  width: 1px;\n  background: repeating-linear-gradient(to bottom, #8a9277 0 4px, transparent 4px 8px);\n}\n\n.timeline li {\n  position: relative;\n  display: grid;\n  grid-template-columns: var(--icon-width) minmax(0, 1fr);\n  column-gap: var(--timeline-gap);\n  align-items: start;\n  padding-block: .5rem .9rem;\n}\n\n.timeline li::before {\n  content: \"\";\n  position: absolute;\n  top: 1.3rem;\n  left: calc(var(--thread-x) - 3px);\n  width: 7px;\n  height: 7px;\n  border-radius: 50%;\n  background: #828b70;\n  box-shadow: 0 0 0 3px var(--paper);\n}\n\n.timeline time {\n  grid-area: 1 / 2;\n  font: 500 .8125rem/1.3 var(--sans);\n  font-variant-numeric: tabular-nums;\n  padding-top: .3rem;\n}\n\n.timeline-icon {\n  grid-area: 1 / 1 / 3;\n  width: 100%;\n  aspect-ratio: 2 / 3;\n  background-image: url('data:image/webp;base64,');\n  background-size: 300% 200%;\n  background-repeat: no-repeat;\n}\n\n.timeline-icon[data-icon=\"rings\"] { background-position: 50% 0; }\n.timeline-icon[data-icon=\"glasses\"] { background-position: 100% 0; }\n.timeline-icon[data-icon=\"leaf\"] { background-position: 0 100%; }\n.timeline-icon[data-icon=\"dinner\"] { background-position: 50% 100%; }\n.timeline-icon[data-icon=\"music\"] { background-position: 100% 100%; }\n.timeline li > div { grid-area: 2 / 2; }\n.timeline h3 { margin-top: .25rem; font-size: clamp(1.375rem, 3.5cqw, 1.75rem); line-height: 1.16; }\n.timeline li p { margin-top: .35rem; color: var(--muted); }\n\n.details { text-align: center; }\n.faq-list { text-align: left; max-width: 34rem; margin: 1.5rem auto 0; border-top: 1px solid var(--line); }\ndetails { border-bottom: 1px solid var(--line); }\nsummary {\n  display: flex;\n  justify-content: space-between;\n  align-items: center;\n  gap: 1rem;\n  list-style: none;\n  font: clamp(1.375rem, 3.8cqw, 1.625rem)/1.3 var(--serif);\n  padding: 1rem .25rem;\n  cursor: pointer;\n}\n\nsummary::-webkit-details-marker { display: none; }\nsummary::after { content: \"+\"; font: 1.125rem var(--sans); color: var(--muted); }\ndetails[open] summary::after { content: \"−\"; }\ndetails > p { color: var(--muted); padding: 0 .25rem 1.25rem; }\n\n.gift-section { padding-block: 1.75rem 3.25rem; }\n.gift-copy > p, .rsvp-section > p {\n  max-width: 39ch;\n  margin: 1rem auto 0;\n  color: var(--muted);\n}\n\n.rsvp-section { padding-block: 2rem 2.75rem; }\n.rsvp-section h2 { font-size: clamp(2.4rem, 6.5cqw, 3.625rem); }\n.rsvp-section h2 em { font-style: italic; }\n.rsvp-section .primary-button { margin-top: 1.25rem; }\n\nfooter { text-align: center; padding: 1rem 0 0; }\n.footer-monogram { display: inline-flex; align-items: center; min-height: 44px; font-size: 2rem; }\nfooter > p { font-size: 1.25rem; padding-inline: 1rem; font-style: italic; margin-top: .35rem; }\nfooter > span { display: block; font: .75rem var(--sans); letter-spacing: .035em; margin-top: .65rem; }\n.footer-replay { margin: .75rem auto 0; color: var(--muted); border: 0; background: none; text-decoration: underline; text-underline-offset: 4px; }\n.farewell-art { width: min(92%, 36rem); height: auto; margin: 1rem auto 0; }\n\n/* Dialogs and editing retain their existing functions. */\ndialog{width:550px;max-width:calc(100% - 32px);max-height:90svh;padding:42px;border:1px solid #c9cbb6;background:var(--paper);color:var(--ink);overflow:auto;box-shadow:0 25px 90px #26342135}dialog::backdrop{background:#27332178;backdrop-filter:blur(7px)}.dialog-close{position:absolute;top:10px;right:15px;border:0;background:none;font-size:29px;line-height:1;padding:8px;min-width:44px;min-height:44px}dialog h2{font-size:clamp(2rem, 7vw, 2.5rem);margin:0 30px 16px}form{display:grid;gap:20px}label{display:flex;flex-direction:column;gap:7px;font:13px/1.65 var(--sans)}input,textarea{width:100%;background:#fffcf6;border:1px solid #c4cbb4;padding:11px;font:16px var(--sans);border-radius:0}fieldset{border:0;padding:0;margin:0}legend{font:13px var(--sans);margin-bottom:10px}.radio-label{display:flex;flex-direction:row;align-items:center;margin:10px 0;font-size:13px;min-height:36px}.radio-label input{width:auto;accent-color:var(--ink)}.form-row{display:grid;grid-template-columns:1fr 1fr;gap:18px}.form-note,#rsvp-result{font:13px/1.6 var(--sans);color:var(--muted)}#rsvp-note:not(:last-child){margin-bottom:1rem}#photo-dialog{width:auto;max-width:90vw;padding:28px}#large-photo{max-height:78svh;width:auto;height:auto}.editor-bar{position:fixed;bottom:15px;left:15px;right:15px;z-index:30;display:flex;justify-content:space-between;align-items:center;gap:15px;background:var(--ink);color:var(--paper);padding:12px 18px;font:11px var(--sans)}.editor-bar button{background:var(--paper);border:0;padding:8px 12px;font:11px var(--sans)}.editor-note{font:11px/1.8 var(--sans);color:var(--muted);margin:15px 0 25px}.image-input small{font-size:10px;color:var(--muted)}#export-html{margin-top:25px}.noscript-note{text-align:center;padding:20px}\n.motion-enabled .reveal{opacity:0;transform:translateY(15px);transition:opacity .8s ease,transform .8s ease}.motion-enabled .reveal:focus-within,.motion-enabled .reveal.is-visible{opacity:1;transform:none}@keyframes soft-arrive{from{opacity:.3;transform:translateY(8px)}to{opacity:1;transform:none}}\n\n@media (min-width: 701px) {\n  .hero-art { aspect-ratio: 4 / 3; }\n  .hero-copy { top: 8%; left: 18%; width: 64%; }\n  .hero h1 { flex-direction: row; justify-content: center; align-items: baseline; font-size: clamp(2.4rem, 7.3cqw, 4rem); }\n  .hero h1 em { font-size: .7em; margin: 0 .3em; }\n  .hero-date { margin-top: 17px; }\n  .hero-place { margin-top: 9px; }\n}\n\n@media (max-width: 700px) {\n  .hero-copy { top: 10.5%; left: 20%; width: 60%; }\n  .hero h1 { font-size: clamp(2.125rem, 10.8cqw, 3.875rem); }\n  .hero h1 em { font-size: .64em; margin: .13em 0; }\n  .hero-date { font-size: clamp(.875rem, 4cqw, 1.125rem); letter-spacing: .06em; margin-top: 12px; }\n  .hero-place { margin-top: 7px; }\n  .site-header { display: grid; grid-template-columns: auto 1fr; gap: 0 1rem; }\n  .site-header nav { grid-row: 2; grid-column: 1 / -1; justify-content: space-between; }\n  .nav-rsvp { justify-self: end; }\n  .story { grid-template-columns: minmax(0, 1fr); text-align: center; }\n  .story-copy > p { max-width: 42ch; margin-inline: auto; }\n  .photo-duo { max-width: 27rem; margin-inline: auto; }\n  dialog { padding: 28px 22px; }\n}\n\n@media (max-width: 560px) {\n  .venue-grid { grid-template-columns: minmax(0, 1fr); gap: 2.4rem; }\n  .venue-art { height: clamp(12.5rem, 66cqw, 19rem); }\n  .editor-bar { left: 8px; right: 8px; bottom: 8px; font-size: .6875rem; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  html { scroll-behavior: auto; }\n  *, *::before, *::after { animation: none !important; transition: none !important; }\n  .motion-enabled .reveal { opacity: 1; transform: none; }\n}\n\n@media print {\n  .opening, .site-header, .hero-discover, .calendar-button, .footer-replay, .editor-bar, dialog, .primary-button { display: none !important; }\n  .hero { padding-bottom: 0; }\n  .section-pad { padding: 40px; }\n  .reveal { opacity: 1 !important; transform: none !important; }\n  .venue-card, .photo-frame, details { break-inside: avoid; }\n}\n\n/* The card leaves reveal the already rendered first scene. */\n.opening{position:fixed;inset:0;z-index:60;overflow:hidden;background:transparent;isolation:isolate}.opening:focus{outline:0}.opening-active{overflow:hidden}.gatefold{position:absolute;inset:0;perspective:1800px;transform-style:preserve-3d}.gate-door,.seal-carrier{position:absolute;top:0;bottom:0;width:50%;transform-style:preserve-3d;transition:transform 2.85s cubic-bezier(.35,0,.18,1);will-change:transform}.gate-left{left:0;transform-origin:left center;z-index:2}.gate-right{right:0;transform-origin:right center;z-index:3}.seal-carrier{right:0;transform-origin:right center;z-index:10;pointer-events:none}.door-face,.door-back{position:absolute;inset:0;backface-visibility:hidden;background:#929e80 url('data:image/svg+xml;base64,') repeat;background-size:480px 720px;border-top:1px solid #d6d9b866;border-bottom:1px solid #45593866}.door-face:before{content:\"\";position:absolute;inset:18px;border:1px solid #e7e8c928;pointer-events:none}.gate-left .door-face:before{border-right:0;right:0}.gate-right .door-face:before{border-left:0;left:0}.gate-left .door-face{box-shadow:inset -3px 0 3px #26351fcc,inset -20px 0 32px #2a3c2233,8px 0 24px #25301b33}.gate-right .door-face{box-shadow:inset 2px 0 2px #d9dfb77a,inset 14px 0 22px #26321e2b,-2px 0 7px #20331bcc}.door-face:after{content:\"\";position:absolute;inset:0;background:linear-gradient(110deg,#f9f1c91a,transparent 60%,#21301920)}.door-back{transform:rotateY(180deg) translateZ(2px);background-color:#d0d4ba;background-blend-mode:soft-light}.wax-seal{position:absolute;left:0;top:48%;width:210px;aspect-ratio:1086/1448;padding:0;border:0;background:none;transform:translate3d(-50%,-50%,28px);backface-visibility:hidden;pointer-events:auto;filter:drop-shadow(-3px 10px 5px #23332069);transition:transform .35s,filter .35s}.wax-seal>img{width:100%;height:auto;pointer-events:none}.wax-seal:hover{transform:translate3d(-50%,-50%,34px) scale(1.025);filter:drop-shadow(-4px 13px 7px #26301a78)}.wax-seal:focus-visible{outline:1px solid #fdf4d7;outline-offset:12px;border-radius:40%}.seal-monogram{position:absolute;top:52%;left:0;right:0;transform:translateY(-50%);display:flex;justify-content:center;align-items:baseline;gap:4px;font:63px/1 var(--script);letter-spacing:0;color:#ab8446;text-shadow:0 -1px #fff8df,1px 1px #694c2959;pointer-events:none}.seal-monogram em{font:italic 30px var(--serif);margin-inline:1px}.opening-note{position:absolute;top:11%;left:15px;right:15px;text-align:center;color:#202e21;z-index:20;font:500 .6875rem/1.5 var(--sans);letter-spacing:.2em;text-shadow:0 1px 2px #e6ead166;transition:opacity .6s}.opening-names{font:46px/1.2 var(--script);letter-spacing:0;margin-top:17px}.opening-bottom{position:absolute;left:20px;right:20px;bottom:9%;z-index:20;text-align:center;transition:opacity .5s,transform .8s}.opening-prompt{font:italic 25px var(--serif);color:#202e21;margin-bottom:16px}.opening-bottom .text-button{font-size:.75rem;letter-spacing:.06em;color:#fffaf0;background:#2f4031;border:1px solid #2f4031;border-radius:2px;padding:9px 14px;gap:15px}.opening-date{font:19px var(--serif);color:#202e21;letter-spacing:1px;margin-top:20px}.is-opening .gate-left{transform:rotateY(-112deg);transition-delay:.12s}.is-opening .gate-right,.is-opening .seal-carrier{transform:rotateY(112deg);transition-delay:0s}.is-opening .opening-note{opacity:0}.is-opening .opening-bottom{opacity:0;transform:translateY(12px)}.opening.is-opening,.is-opening .wax-seal{pointer-events:none}.is-opening .wax-seal{transform:translate3d(-50%,-50%,28px)}\n@media(max-width:700px){.gatefold{perspective:1100px}.door-face,.door-back{background-size:360px 540px}.wax-seal{width:176px}.seal-monogram{font-size:53px}.seal-monogram em{font-size:25px}.opening-note{top:12%;letter-spacing:.16em}.opening-names{font-size:42px}.opening-bottom{bottom:11%}.opening-prompt{font-size:22px}.opening-date{font-size:18px}}\n@media(max-height:560px){.opening-note{top:5%}.opening-names{font-size:30px;margin-top:7px}.wax-seal{width:116px;top:49%}.seal-monogram{font-size:37px}.seal-monogram em{font-size:19px}.opening-bottom{bottom:4%}.opening-prompt{font-size:18px;margin-bottom:5px}.opening-date{font-size:13px;margin-top:8px}}\n@media(prefers-reduced-motion:reduce){.opening.is-opening{visibility:hidden}}\n\n.opening-bottom .text-button:focus-visible { outline-color: #fffaf0; }\n\u003c/style>\n\n  \u003cscript id=\"wedding-config\">/* Alle Angaben können hier ersetzt werden. Keine Installation nötig.\n   Namen, Hochzeitsdatum und Locations sind bestätigt.\n   Zeiten, Rückmeldefrist und weitere Details sind Design-Platzhalter. */\nwindow.WEDDING = {\n  names: ['Marie', 'Simon'],\n  date: '2027-08-28',\n  dateLabel: '28. August 2027',\n  weekday: 'Samstag',\n  region: 'Schermbeck',\n  invitation: 'Ein Tag voller Liebe.\\nUnd ihr mittendrin.',\n  intro: 'Aus einem kleinen Wir wird ein großes Für immer. Wir heiraten – und möchten diesen besonderen Tag mit den Menschen feiern, die unser Leben schöner machen. Mit euch.',\n  quote: 'Mit dir fühlt sich jeder Ort\\nwie Zuhause an.',\n  story: 'Manchmal beginnt das größte Abenteuer ganz leise. Mit einem Blick, einem Lachen und dem Gefühl, angekommen zu sein. Jetzt sagen wir Ja – zu uns, zu allem, was kommt, und zu einem Leben voller gemeinsamer Geschichten.',\n  photos: {\n    couple: '__INVITATION_PHOTO_0__',\n    hands: '__INVITATION_PHOTO_1__',\n    church: '__INVITATION_PHOTO_2__',\n    party: '__INVITATION_PHOTO_3__',\n  },\n  ceremony: {\n    name: 'Reformierte Kirche',\n    type: 'Unsere standesamtliche Trauung',\n    time: '14:00 Uhr',\n    arrival: 'Ankommen ab 13:30 Uhr',\n    address: 'Schermbeck · die genaue Adresse folgt',\n    mapQuery: 'Reformierte Kirche Schermbeck',\n    text: 'Hier beginnt unser Für immer. Seid dabei, wenn aus zwei Geschichten eine gemeinsame wird.'\n  },\n  party: {\n    name: 'Mago Restaurant & Bar',\n    type: 'Dinner, Drinks & Dancing',\n    time: '17:00 Uhr',\n    arrival: 'Ein Abend, der bleiben darf',\n    address: 'Schermbeck · die genaue Adresse folgt',\n    mapQuery: 'Mago Restaurant und Bar Schermbeck',\n    text: 'Gute Gespräche, ein festliches Dinner und die Tanzfläche voller Lieblingsmenschen. Wir feiern mit euch bis in die Nacht.'\n  },\n  timeline: [\n    { time: '13:30', title: 'Hallo, Lieblingsmenschen', text: 'Ankommen an der Reformierten Kirche.', icon: 'sun' },\n    { time: '14:00', title: 'Ein kleines Wort. Für immer.', text: 'Unsere standesamtliche Trauung.', icon: 'rings' },\n    { time: '15:00', title: 'Auf die Liebe', text: 'Anstoßen, Umarmungen und gemeinsame Fotos.', icon: 'glasses' },\n    { time: '17:00', title: 'Bienvenue bei Mago', text: 'Aperitif im Mago Restaurant & Bar.', icon: 'leaf' },\n    { time: '18:00', title: 'Ein Tisch voller Geschichten', text: 'Zeit für ein festliches Dinner.', icon: 'dinner' },\n    { time: '20:30', title: 'Barfuß wäre auch okay', text: 'Erster Tanz. Gute Musik. Eine lange Nacht.', icon: 'music' }\n  ],\n  details: [\n    { title: 'Wie kommen wir hin?', text: 'Beide Locations liegen in Schermbeck. Details zu Parkplätzen und einem möglichen Shuttle ergänzen wir hier rechtzeitig.' },\n    { title: 'Wo können wir bleiben?', text: 'Macht ein kleines Wochenende daraus. Unsere Hotelempfehlungen und Informationen zu reservierten Zimmern folgen hier.' },\n    { title: 'Ein Geschenk für euch?', text: 'Das schönste Geschenk ist, dass ihr dabei seid. Wer uns darüber hinaus eine Freude machen möchte, darf etwas zu unserer nächsten gemeinsamen Reise beitragen.' },\n    { title: 'Kinder, Essen & Wünsche', text: 'Sagt uns bei eurer Rückmeldung gern, mit wem ihr kommt und ob wir Allergien, vegetarische Wünsche oder andere Bedürfnisse berücksichtigen dürfen.' },\n    { title: 'Noch eine Frage?', text: 'Unsere Kontaktdaten und die unserer Trauzeugen ergänzen wir hier. Bis dahin: Wir freuen uns auf euch!' }\n  ],\n  rsvpDeadline: '1. Mai 2027',\n  rsvpEmail: '', // Später eure echte E-Mail eintragen; Antworten werden als E-Mail vorbereitet.\n  scheduleConfirmed: false, // Erst nach Bestätigung der Uhrzeiten aktivieren.\n  calendar: { startTime: '14:00', endTime: '23:59', timezone: 'Europe/Berlin' },\n  footer: 'Mit Liebe geplant. Mit euch unvergesslich.'\n};\n\u003c/script>\n\n\n\u003c/head>\n\u003cbody>\n  \u003ca class=\"skip-link\" href=\"#einladung\">Zur Einladung\u003c/a>\n  \u003cdiv class=\"opening\" id=\"opening\" role=\"dialog\" aria-modal=\"true\" aria-label=\"Eure Einladung öffnen\" tabindex=\"-1\" hidden>\n    \u003cdiv class=\"gatefold\">\n      \u003cdiv class=\"gate-door gate-left\" aria-hidden=\"true\">\u003cdiv class=\"door-face\">\u003c/div>\u003cdiv class=\"door-back\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"gate-door gate-right\" aria-hidden=\"true\">\u003cdiv class=\"door-face\">\u003c/div>\u003cdiv class=\"door-back\">\u003c/div>\u003c/div>\n      \u003cdiv class=\"seal-carrier\">\n        \u003cbutton class=\"wax-seal\" id=\"open-invitation\" aria-label=\"Einladung über das Siegel öffnen\">\u003cimg src=\"data:image/webp;base64,\" alt=\"\" width=\"600\" height=\"800\" fetchpriority=\"high\">\u003cspan class=\"seal-monogram\">\u003cspan data-initial=\"0\">M\u003c/span>\u003cem>&amp;\u003c/em>\u003cspan data-initial=\"1\">S\u003c/span>\u003c/span>\u003c/button>\n      \u003c/div>\n    \u003c/div>\n    \u003cdiv class=\"opening-note\">\u003cspan>FÜR UNSERE LIEBLINGSMENSCHEN\u003c/span>\u003cp class=\"opening-names names-inline\">Marie &amp; Simon\u003c/p>\u003c/div>\n    \u003cdiv class=\"opening-bottom\">\u003cp class=\"opening-prompt\">Ein kleiner Moment. Ein großes Ja.\u003c/p>\u003cbutton class=\"text-button\" id=\"open-text\">Zum Öffnen berühren \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/button>\u003cp class=\"opening-date\" data-bind=\"dateLabel\">28. August 2027\u003c/p>\u003c/div>\n  \u003c/div>\n  \u003cdiv class=\"invitation-sheet\">\n  \u003cmain id=\"einladung\">\n    \u003csection class=\"hero\" aria-labelledby=\"hero-title\">\n      \u003cpicture class=\"hero-art\">\u003csource media=\"(min-width:701px)\" srcset=\"data:image/webp;base64,\" width=\"1448\" height=\"1086\">\u003cimg class=\"garden-frame\" src=\"data:image/webp;base64,\" alt=\"\" width=\"1024\" height=\"1536\" fetchpriority=\"high\">\u003c/picture>\n      \u003cdiv class=\"hero-copy\">\n        \u003ch1 id=\"hero-title\" tabindex=\"-1\">\u003cspan data-name=\"0\">Marie\u003c/span>\u003cem>&amp;\u003c/em>\u003cspan data-name=\"1\">Simon\u003c/span>\u003c/h1>\n        \u003cp class=\"hero-date\" data-bind=\"dateLabel\">28. August 2027\u003c/p>\n        \u003cp class=\"hero-place\" data-bind=\"region\">Schermbeck\u003c/p>\n      \u003c/div>\n      \u003ca class=\"hero-discover\" href=\"#willkommen\">Unsere Einladung entdecken \u003cspan aria-hidden=\"true\">↓\u003c/span>\u003c/a>\n\n    \u003c/section>\n\n  \u003cheader class=\"site-header\">\n    \u003ca class=\"brand\" href=\"#einladung\" aria-label=\"Zum Anfang\">\u003cspan class=\"initials\">M · S\u003c/span>\u003c/a>\n    \u003cnav aria-label=\"Einladung\">\n      \u003ca href=\"#orte\">Die Orte\u003c/a>\u003ca href=\"#unser-tag\">Ablauf\u003c/a>\u003ca href=\"#gut-zu-wissen\">Gut zu wissen\u003c/a>\n    \u003c/nav>\n    \u003cbutton class=\"nav-rsvp\" data-rsvp>Zur Rückmeldung \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/button>\n  \u003c/header>\n    \u003csection class=\"welcome textile-panel\" id=\"willkommen\" aria-labelledby=\"welcome-title\">\n      \u003cimg class=\"panel-art\" src=\"data:image/webp;base64,\" alt=\"\" width=\"1024\" height=\"1536\" loading=\"lazy\">\n      \u003cdiv class=\"welcome-copy panel-copy reveal\">\u003ch2 id=\"welcome-title\" data-bind=\"invitation\">\u003c/h2>\u003cp data-bind=\"intro\">\u003c/p>\u003cspan class=\"signature names-inline\">Marie &amp; Simon\u003c/span>\u003c/div>\n    \u003c/section>\n\n    \u003csection class=\"date-section section-pad\" id=\"datum\" aria-labelledby=\"date-title\">\n\n      \u003cp class=\"eyebrow reveal\">BIS ZU UNSEREM GROSSEN TAG\u003c/p>\n      \u003ch2 id=\"date-title\" class=\"reveal\">Countdown\u003c/h2>\n      \u003cdiv class=\"date-display reveal\">\u003cspan data-bind=\"weekday\">Samstag\u003c/span>\u003cstrong data-bind=\"dateLabel\">28. August 2027\u003c/strong>\u003cspan data-bind=\"region\">Schermbeck\u003c/span>\u003c/div>\n      \u003cdiv class=\"countdown reveal\" aria-label=\"Zeit bis zur Hochzeit\">\u003cdiv>\u003cimg src=\"data:image/webp;base64,\" alt=\"\" width=\"480\" height=\"480\" loading=\"lazy\">\u003cstrong id=\"count-days\">254\u003c/strong>\u003cspan>TAGE\u003c/span>\u003c/div>\u003cdiv>\u003cimg src=\"data:image/webp;base64,\" alt=\"\" width=\"480\" height=\"480\" loading=\"lazy\">\u003cstrong id=\"count-hours\">00\u003c/strong>\u003cspan>STUNDEN\u003c/span>\u003c/div>\u003cdiv>\u003cimg src=\"data:image/webp;base64,\" alt=\"\" width=\"480\" height=\"480\" loading=\"lazy\">\u003cstrong id=\"count-minutes\">00\u003c/strong>\u003cspan>MINUTEN\u003c/span>\u003c/div>\u003c/div>\n      \u003cbutton class=\"text-button calendar-button reveal\" id=\"save-date\">Datum im Kalender vormerken \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/button>\n      \u003cp class=\"countdown-note\" id=\"countdown-note\" hidden>Unser Für immer hat begonnen.\u003c/p>\n    \u003c/section>\n\n    \u003csection class=\"venues section-pad\" id=\"orte\" aria-labelledby=\"venues-title\">\n\n      \u003cdiv class=\"venues-intro reveal\">\n        \u003cimg class=\"section-ornament venue-ornament\" src=\"data:image/webp;base64,\" alt=\"\" width=\"624\" height=\"208\" loading=\"lazy\">\n        \u003ch2 id=\"venues-title\">Trauung &amp; Feier\u003c/h2>\n        \u003cp class=\"section-note\" data-provisional>Die Uhrzeiten sind vorläufig.\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"venue-grid\">\n        \u003carticle class=\"venue-card reveal\">\n          \u003cdiv class=\"venue-art venue-church\">\u003cimg data-photo=\"church\" alt=\"Gestickte Illustration der Reformierten Kirche in Schermbeck\" hidden>\u003cimg class=\"venue-fallback\" src=\"data:image/svg+xml;base64,\" alt=\"Florale Illustration der Reformierten Kirche\" width=\"420\" height=\"370\" loading=\"lazy\">\u003c/div>\n          \u003cdiv class=\"venue-info\">\u003cp class=\"eyebrow\" data-bind=\"ceremony.type\">\u003c/p>\u003ch3 data-bind=\"ceremony.name\">\u003c/h3>\u003cp class=\"venue-time\" data-bind=\"ceremony.time\">\u003c/p>\u003cp class=\"venue-arrival\" data-bind=\"ceremony.arrival\">\u003c/p>\u003cp class=\"venue-description\" data-bind=\"ceremony.text\">\u003c/p>\u003cp class=\"venue-address\" data-bind=\"ceremony.address\">\u003c/p>\u003ca class=\"text-button map-link\" data-map=\"ceremony\" target=\"_blank\" rel=\"noopener noreferrer\">Den Weg zur Trauung finden \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/a>\u003c/div>\n        \u003c/article>\n        \u003carticle class=\"venue-card reveal\">\n          \u003cdiv class=\"venue-art venue-party\">\u003cimg data-photo=\"party\" alt=\"Gestickte Illustration des Mago Restaurant & Bar\" hidden>\u003cimg class=\"venue-fallback\" src=\"data:image/svg+xml;base64,\" alt=\"Florale Illustration des Mago Restaurant & Bar\" width=\"400\" height=\"320\" loading=\"lazy\">\u003c/div>\n          \u003cdiv class=\"venue-info\">\u003cp class=\"eyebrow\" data-bind=\"party.type\">\u003c/p>\u003ch3 data-bind=\"party.name\">\u003c/h3>\u003cp class=\"venue-time\" data-bind=\"party.time\">\u003c/p>\u003cp class=\"venue-arrival\" data-bind=\"party.arrival\">\u003c/p>\u003cp class=\"venue-description\" data-bind=\"party.text\">\u003c/p>\u003cp class=\"venue-address\" data-bind=\"party.address\">\u003c/p>\u003ca class=\"text-button map-link\" data-map=\"party\" target=\"_blank\" rel=\"noopener noreferrer\">Den Weg zur Feier finden \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/a>\u003c/div>\n        \u003c/article>\n      \u003c/div>\n    \u003c/section>\n\n    \u003csection class=\"story section-pad\" id=\"unsere-geschichte\" aria-labelledby=\"story-title\">\n      \u003cdiv class=\"story-framed story-copy reveal\">\n        \u003ch2 id=\"story-title\">Unsere Geschichte\u003c/h2>\n        \u003cp data-bind=\"story\">\u003c/p>\n      \u003c/div>\n      \u003cdiv class=\"story-photos reveal\">\n        \u003cdiv class=\"photo-duo\">\n          \u003cfigure class=\"photo-main photo-frame\">\n            \u003cimg data-photo=\"couple\" alt=\"Marie und Simon, ein gemeinsamer Lieblingsmoment\" hidden>\n            \u003cdiv class=\"photo-fallback\">\u003cimg src=\"data:image/svg+xml;base64,\" alt=\"\">\u003cspan>Wir zwei.\u003c/span>\u003csmall>Unser Lieblingsmoment\u003c/small>\u003c/div>\n            \u003cfigcaption>Du, ich und alles, was kommt.\u003c/figcaption>\n          \u003c/figure>\n          \u003cfigure class=\"photo-detail photo-frame\">\n            \u003cimg data-photo=\"hands\" alt=\"Unsere Hände und der Verlobungsring\" hidden>\n            \u003cdiv class=\"photo-fallback\">\u003cspan class=\"fallback-amp\">&amp;\u003c/span>\u003cspan>Für immer.\u003c/span>\u003c/div>\n            \u003cfigcaption>Ein kleines Versprechen.\u003c/figcaption>\n          \u003c/figure>\n        \u003c/div>\n      \u003c/div>\n      \u003cp class=\"story-quote reveal\" data-bind=\"quote\">\u003c/p>\n    \u003c/section>\n\n    \u003csection class=\"timeline-section section-pad\" id=\"unser-tag\" aria-labelledby=\"timeline-title\">\n      \u003cdiv class=\"timeline-header reveal\">\u003cp class=\"eyebrow\">VOM JA BIS ZUM LETZTEN LIED\u003c/p>\u003ch2 id=\"timeline-title\">Ein Tag, der bleibt.\u003c/h2>\u003cp class=\"section-note\" data-provisional>Die Uhrzeiten sind vorläufig.\u003c/p>\u003c/div>\n      \u003col class=\"timeline\" id=\"timeline\">\u003c/ol>\n    \u003c/section>\n\n    \u003csection class=\"details section-pad\" id=\"gut-zu-wissen\" aria-labelledby=\"details-title\">\n\n      \u003cdiv class=\"details-layout\">\u003cdiv class=\"details-title reveal\">\u003ch2 id=\"details-title\">Gut zu wissen\u003c/h2>\u003c/div>\u003cdiv class=\"faq-list reveal\" id=\"faq-list\">\u003c/div>\u003c/div>\n    \u003c/section>\n\n    \u003csection class=\"gift-section section-pad\" aria-labelledby=\"gift-title\">\n      \u003cimg class=\"section-ornament gift-ornament\" src=\"data:image/webp;base64,\" alt=\"\" width=\"624\" height=\"208\" loading=\"lazy\">\n      \u003cdiv class=\"gift-copy reveal\">\n        \u003ch2 id=\"gift-title\" data-detail-title=\"2\">\u003c/h2>\n        \u003cp data-detail-text=\"2\">\u003c/p>\n      \u003c/div>\n    \u003c/section>\n\n    \u003csection class=\"rsvp-section section-pad\" id=\"rueckmeldung\" aria-labelledby=\"rsvp-title\">\n\n      \u003ch2 id=\"rsvp-title\" class=\"reveal\">Mit euch wird es\u003cbr>\u003cem>unvergesslich.\u003c/em>\u003c/h2>\n      \u003cp class=\"reveal\" id=\"rsvp-intro\">Lasst uns bis zum \u003cspan data-bind=\"rsvpDeadline\">\u003c/span> wissen, ob wir mit euch feiern dürfen.\u003c/p>\n      \u003cp class=\"reveal\" id=\"rsvp-availability\" hidden>Die Rückmeldung öffnet in Kürze.\u003c/p>\n      \u003cbutton class=\"primary-button reveal\" data-rsvp>Zur Rückmeldung \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/button>\n    \u003c/section>\n  \u003c/main>\n  \u003cfooter>\u003ca class=\"footer-monogram initials\" href=\"#einladung\">M · S\u003c/a>\u003cp data-bind=\"footer\">\u003c/p>\u003cspan>\u003cspan data-bind=\"dateLabel\">\u003c/span> · \u003cspan data-bind=\"region\">\u003c/span>\u003c/span>\u003cbutton class=\"footer-replay\" id=\"replay\">Einladung noch einmal öffnen\u003c/button>\u003cimg class=\"farewell-art\" data-farewell-art src=\"data:image/webp;base64,\" alt=\"Zwei gestickte Schwäne, deren Hälse ein Herz bilden\" width=\"1536\" height=\"1024\" loading=\"lazy\">\u003c/footer>\n  \u003c/div>\n\n  \u003cdialog id=\"rsvp-dialog\" aria-labelledby=\"rsvp-dialog-title\">\n    \u003cbutton class=\"dialog-close\" data-close aria-label=\"Schließen\">×\u003c/button>\n\n    \u003ch2 id=\"rsvp-dialog-title\">Rückmeldung\u003c/h2>\n    \u003cp class=\"form-note\" id=\"rsvp-note\">\u003c/p>\n    \u003cform id=\"rsvp-form\" hidden>\n      \u003clabel>Eure Namen\u003cinput name=\"names\" autocomplete=\"name\" required placeholder=\"Vor- und Nachnamen\">\u003c/label>\n      \u003cfieldset>\u003clegend>Seid ihr dabei?\u003c/legend>\u003clabel class=\"radio-label\">\u003cinput type=\"radio\" name=\"attendance\" value=\"Ja, wir feiern mit euch!\" checked> Ja, von Herzen gern.\u003c/label>\u003clabel class=\"radio-label\">\u003cinput type=\"radio\" name=\"attendance\" value=\"Leider können wir nicht dabei sein.\"> Leider schaffen wir es nicht.\u003c/label>\u003c/fieldset>\n      \u003cdiv class=\"form-row\" id=\"rsvp-party\">\u003clabel>Erwachsene\u003cinput name=\"adults\" type=\"number\" min=\"1\" max=\"20\" value=\"2\" required>\u003c/label>\u003clabel>Kinder\u003cinput name=\"children\" type=\"number\" min=\"0\" max=\"20\" value=\"0\" required>\u003c/label>\u003c/div>\n      \u003clabel>Wünsche & liebe Worte\u003ctextarea name=\"message\" rows=\"3\" placeholder=\"Allergien, Essenswünsche oder etwas, das ihr uns sagen möchtet …\">\u003c/textarea>\u003c/label>\n      \u003cbutton class=\"primary-button\" type=\"submit\">Antwort vorbereiten \u003cspan aria-hidden=\"true\">↗︎\u003c/span>\u003c/button>\n      \u003cp id=\"rsvp-result\" role=\"status\" hidden>\u003c/p>\n    \u003c/form>\n  \u003c/dialog>\n  \u003cdialog id=\"photo-dialog\" aria-label=\"Foto in Großansicht\">\u003cbutton class=\"dialog-close\" data-close aria-label=\"Schließen\">×\u003c/button>\u003cimg id=\"large-photo\" alt=\"\">\u003c/dialog>\n  \u003cnoscript>\u003cp class=\"noscript-note\">Bitte aktiviert JavaScript, damit alle Angaben und Interaktionen der Einladung angezeigt werden.\u003c/p>\u003c/noscript>\n\u003cscript>(() => {\n  'use strict';\n  const originalHTML = '\u003c!doctype html>\\n' + document.documentElement.outerHTML;\n  const config = window.WEDDING;\n  const $ = (s) => document.querySelector(s);\n  const $$ = (s) => [...document.querySelectorAll(s)];\n  const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;\n  let activeTrigger = null;\n  const pathValue = (path) => path.split('.').reduce((v,k) => v?.[k], config);\n  const inlineNames = () => config.names.join(' & ');\n\n  function render() {\n    $$('[data-bind]').forEach(el => { el.textContent = pathValue(el.dataset.bind) ?? ''; });\n    $$('[data-name]').forEach(el => { el.textContent = config.names[+el.dataset.name] ?? ''; });\n    $$('[data-initial]').forEach(el => { el.textContent = [...(config.names[+el.dataset.initial] || '').trim()][0] || ''; });\n    $$('.names-inline').forEach(el => { el.textContent = inlineNames(); });\n    $$('.initials').forEach(el => { el.textContent = config.names.map(n => [...n.trim()][0] || '').join(' · '); });\n    document.title = inlineNames() + ' · Wir heiraten';\n    $$('[data-map]').forEach(link => {\n      const route = new URL('https://www.google.com/maps/dir/');\n      route.searchParams.set('api', '1');\n      route.searchParams.set('destination', config[link.dataset.map].mapQuery);\n      link.href = route.href;\n    });\n    $('#timeline').replaceChildren();\n    config.timeline.forEach(item => {\n      const li = document.createElement('li'); li.className = 'reveal';\n      const time = document.createElement('time'); time.textContent = item.time; time.dateTime = item.time;\n      const icon = document.createElement('span'); icon.className = 'timeline-icon'; icon.setAttribute('aria-hidden','true');\n      icon.dataset.icon = item.icon;\n      const copy = document.createElement('div'), title = document.createElement('h3'), text = document.createElement('p');\n      title.textContent = item.title; text.textContent = item.text; copy.append(title,text); li.append(time,icon,copy); $('#timeline').append(li);\n    });\n    $('#faq-list').replaceChildren();\n    $$('[data-detail-title]').forEach(el => { el.textContent = config.details[+el.dataset.detailTitle]?.title || ''; });\n    $$('[data-detail-text]').forEach(el => { el.textContent = config.details[+el.dataset.detailText]?.text || ''; });\n    config.details.filter((_, i) => i !== 2).forEach((item,i) => {\n      const details = document.createElement('details'), summary = document.createElement('summary'), text = document.createElement('p');\n      summary.textContent = item.title; text.textContent = item.text; details.append(summary,text); if (i === 0) details.open = true; $('#faq-list').append(details);\n    });\n    const rsvpOpen = Boolean(config.rsvpEmail);\n    $('#rsvp-form').hidden = !rsvpOpen;\n    $('#rsvp-intro').hidden = !rsvpOpen;\n    $('#rsvp-availability').hidden = rsvpOpen;\n    $('#rsvp-note').textContent = rsvpOpen\n      ? 'Wir bereiten eure Antwort im E-Mail-Programm vor. Dort könnt ihr sie prüfen und absenden.'\n      : 'Die Rückmeldung öffnet in Kürze. Wir freuen uns schon jetzt auf euch.';\n    $$('[data-provisional]').forEach(el => { el.hidden = Boolean(config.scheduleConfirmed); });\n    $$('[data-photo]').forEach(loadPhoto);\n    updateCountdown(); observeReveals();\n  }\n\n  function loadPhoto(el) {\n    const src = config.photos[el.dataset.photo];\n    const fallback = el.parentElement.querySelector('.photo-fallback,.venue-fallback');\n    el.hidden = !src;\n    if (fallback) fallback.hidden = Boolean(src);\n    if (!src) {\n      el.removeAttribute('src');\n      return;\n    }\n    el.loading = 'lazy';\n    el.decoding = 'async';\n    el.onerror = () => {\n      el.hidden = true;\n      if (fallback) fallback.hidden = false;\n    };\n    el.src = src;\n  }\n\n  // A timezone-independent epoch for the Berlin ceremony, including summer time.\n  function eventEpoch() {\n    if (!config.scheduleConfirmed) {\n      // A date-only countdown ends at midnight in the wedding's local time.\n      return localEventEpoch('00:00');\n    }\n    return localEventEpoch(config.calendar.startTime);\n  }\n\n  function localEventEpoch(time) {\n    const tentative = Date.parse(config.date + 'T' + time + ':00Z');\n    if (!Number.isFinite(tentative)) return NaN;\n    const parts = new Intl.DateTimeFormat('en-US',{timeZone:config.calendar.timezone,timeZoneName:'shortOffset',hour:'2-digit'}).formatToParts(tentative);\n    const offset = parts.find(p => p.type === 'timeZoneName')?.value.match(/GMT([+-])(\\d+)(?::(\\d+))?/);\n    const minutes = offset ? (+offset[2]*60 + +(offset[3] || 0)) * (offset[1] === '+' ? 1 : -1) : 0;\n    return tentative - minutes*60000;\n  }\n  function updateCountdown() {\n    const left = eventEpoch() - Date.now();\n    if(!Number.isFinite(left)) return;\n    const minutes = Math.max(0,Math.floor(left/60000));\n    $('#count-days').textContent = String(Math.floor(minutes/1440)).padStart(2,'0');\n    $('#count-hours').textContent = String(Math.floor(minutes%1440/60)).padStart(2,'0');\n    $('#count-minutes').textContent = String(minutes%60).padStart(2,'0');\n    $('#countdown-note').hidden = left > 0;\n  }\n  let observer;\n  function observeReveals() {\n    if(reducedMotion || !('IntersectionObserver' in window)) return;\n    document.body.classList.add('motion-enabled');\n    if(!observer) observer = new IntersectionObserver(entries => entries.forEach(entry => {\n      if(entry.isIntersecting){entry.target.classList.add('is-visible');observer.unobserve(entry.target);}\n    }),{threshold:.07});\n    $$('.reveal:not(.is-visible)').forEach(el => observer.observe(el));\n  }\n\n  async function openInvitation() {\n    if ($('#opening').classList.contains('is-opening') || $('#opening').hasAttribute('aria-busy')) return;\n    $('#opening').setAttribute('aria-busy', 'true');\n    const hero = $('.garden-frame');\n    let readyDeadline;\n    try {\n      await Promise.race([\n        Promise.all([\n          hero?.decode ? hero.decode().catch(() => {}) : Promise.resolve(),\n          document.fonts?.ready || Promise.resolve()\n        ]),\n        new Promise(resolve => { readyDeadline = setTimeout(resolve, 900); })\n      ]);\n    } catch (error) { /* Opening remains available when artwork or fonts fail. */ }\n    finally { clearTimeout(readyDeadline); }\n    $('#opening').removeAttribute('aria-busy');\n    $('#opening').classList.add('is-opening');\n    document.body.classList.add('opening-running');\n    setTimeout(() => {\n      $('#opening').hidden = true;\n      $('#opening').classList.remove('is-opening');\n      document.body.classList.remove('opening-active', 'opening-running');\n      $$('.skip-link,.site-header,main,footer').forEach(el => { el.inert = false; });\n      ($('#hero-title') || $('.hero-discover')).focus({ preventScroll: true });\n    }, reducedMotion ? 0 : 3150);\n    try { sessionStorage.setItem('invitation-opened-linen-v6', 'yes'); } catch (error) {}\n  }\n  function showOpening() {\n    $$('.skip-link,.site-header,main,footer').forEach(el=>{el.inert=true;});window.scrollTo({top:0,behavior:'instant'});\n    $('#opening').hidden = false; document.body.classList.add('opening-active'); $('#opening').focus({preventScroll:true});\n  }\n  $('#opening').addEventListener('keydown',event=>{\n    if(event.key==='Escape'){event.preventDefault();openInvitation();}\n    if(event.key==='Tab'){\n      const first=$('#open-invitation'),last=$('#open-text');\n      if(event.shiftKey&&(document.activeElement===first||document.activeElement===$('#opening'))){event.preventDefault();last.focus();}\n      else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}\n    }\n  });\n  $('#open-invitation').addEventListener('click',openInvitation); $('#open-text').addEventListener('click',openInvitation);\n  $('#replay').addEventListener('click',showOpening);\n  let alreadyOpened = false;\n  try { alreadyOpened = sessionStorage.getItem('invitation-opened-linen-v6') === 'yes'; } catch(e) {}\n  const editMode = new URLSearchParams(location.search).has('edit');\n  if(!alreadyOpened && !location.hash && !editMode) showOpening();\n\n  function openDialog(dialog,trigger) { activeTrigger = trigger; dialog.showModal(); }\n  $$('[data-rsvp]').forEach(button => button.addEventListener('click',() => openDialog($('#rsvp-dialog'),button)));\n  $$('[data-close]').forEach(button => button.addEventListener('click',() => button.closest('dialog').close()));\n  $$('dialog').forEach(dialog => {\n    dialog.addEventListener('click',event => { if(event.target === dialog){const r=dialog.getBoundingClientRect();if(event.clientX\u003cr.left||event.clientX>r.right||event.clientY\u003cr.top||event.clientY>r.bottom)dialog.close();} });\n    dialog.addEventListener('close',() => { activeTrigger?.focus({preventScroll:true}); });\n  });\n  $$('.photo-frame>[data-photo]').forEach(img => {\n    img.tabIndex=0; img.setAttribute('role','button');\n    const show = () => { if(img.hidden || !img.naturalWidth) return; $('#large-photo').src=img.src; $('#large-photo').alt=img.alt; openDialog($('#photo-dialog'),img); };\n    img.addEventListener('click',show); img.addEventListener('keydown',e => {if(e.key==='Enter'||e.key===' '){e.preventDefault();show();}});\n  });\n\n  const rsvpForm = $('#rsvp-form');\n  rsvpForm.addEventListener('change', event => {\n    if (event.target.name !== 'attendance') return;\n    const attending = rsvpForm.elements.attendance[0].checked;\n    $('#rsvp-party').hidden = !attending;\n    rsvpForm.elements.adults.disabled = !attending;\n    rsvpForm.elements.children.disabled = !attending;\n  });\n  $('#rsvp-form').addEventListener('submit',event => {\n    event.preventDefault(); const result = $('#rsvp-result'); result.hidden = false;\n    if(!config.rsvpEmail){result.textContent='Unsere Rückmeldung ist noch nicht geöffnet. Bitte schaut bald wieder vorbei. Es wurde keine Antwort verschickt oder gespeichert.';return;}\n    const data = new FormData(event.currentTarget);\n    const body = ['Liebe ' + inlineNames() + ',', '', data.get('attendance'), 'Namen: ' + data.get('names')];\n    if (data.has('adults')) body.push('Erwachsene: ' + data.get('adults'), 'Kinder: ' + data.get('children'));\n    if (data.get('message')?.trim()) body.push('', 'Wünsche & liebe Worte:', data.get('message').trim());\n    const link = document.createElement('a');\n    link.href = 'mailto:' + encodeURIComponent(config.rsvpEmail) + '?subject=' +\n      encodeURIComponent('Unsere Rückmeldung zu eurer Hochzeit') + '&body=' + encodeURIComponent(body.join('\\r\\n'));\n    link.click();\n    result.textContent = 'Bitte sendet die vorbereitete E-Mail in eurem E-Mail-Programm ab.';\n  });\n\n  function download(content,type,name) {\n    const url = URL.createObjectURL(new Blob([content],{type})); const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),3000);\n  }\n  const icsEscape = value => String(value).replace(/\\\\/g,'\\\\\\\\').replace(/\\n/g,'\\\\n').replace(/,/g,'\\\\,').replace(/;/g,'\\\\;');\n  const utcICS = date => new Date(date).toISOString().replace(/[-:]/g,'').split('.')[0]+'Z';\n  $('#save-date').addEventListener('click',() => {\n    const day = Date.parse(config.date + 'T00:00:00Z');\n    if (!Number.isFinite(day)) return;\n    const nextDay = new Date(day + 86400000).toISOString().slice(0, 10);\n    let dates = ['DTSTART;VALUE=DATE:' + config.date.replaceAll('-', ''),\n      'DTEND;VALUE=DATE:' + nextDay.replaceAll('-', '')];\n    let description = 'Trauung: ' + config.ceremony.name + '\\nFeier: ' + config.party.name + '\\nUhrzeiten folgen.';\n    if (config.scheduleConfirmed) {\n      const start = eventEpoch();\n      const [sh, sm] = config.calendar.startTime.split(':').map(Number);\n      const [eh, em] = config.calendar.endTime.split(':').map(Number);\n      let duration = (eh * 60 + em - sh * 60 - sm) * 60000;\n      if (duration \u003c= 0) duration += 86400000;\n      if (!Number.isFinite(start + duration)) return;\n      dates = ['DTSTART:' + utcICS(start), 'DTEND:' + utcICS(start + duration)];\n      description = 'Trauung: ' + config.ceremony.time + ' · ' + config.ceremony.name +\n        '\\nFeier: ' + config.party.time + ' · ' + config.party.name;\n    }\n    const lines = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Unser Hochzeitsgarten//DE',\n      'CALSCALE:GREGORIAN', 'BEGIN:VEVENT',\n      'UID:' + config.date + '-' + config.names.map(n => encodeURIComponent(n)).join('-') + '@hochzeitsgarten.local',\n      'DTSTAMP:' + utcICS(Date.now()), ...dates, 'SUMMARY:' + icsEscape('Hochzeit von ' + inlineNames()),\n      'LOCATION:' + icsEscape(config.ceremony.name + ', ' + (config.ceremony.address || config.region)),\n      'DESCRIPTION:' + icsEscape(description), 'END:VEVENT', 'END:VCALENDAR'];\n    // RFC 5545 folds by UTF-8 bytes, preserving multibyte characters.\n    const folded=lines.map(line=>{let out='',bytes=0;for(const ch of line){const size=new TextEncoder().encode(ch).length;if(bytes+size>73){out+='\\r\\n ';bytes=1;}out+=ch;bytes+=size;}return out;}).join('\\r\\n')+'\\r\\n';\n    download(folded,'text/calendar;charset=utf-8','Unsere-Hochzeit.ics');\n  });\n\n  function setupEditor() {\n    const bar=document.createElement('div');bar.className='editor-bar';\n    const note=document.createElement('span');note.textContent='Designvorschau · Uhrzeiten & weitere Details sind Platzhalter.';\n    const button=document.createElement('button');button.textContent='Einladung anpassen';bar.append(note,button);document.body.append(bar);\n    const dialog=document.createElement('dialog');dialog.id='editor-dialog';\n    dialog.innerHTML='\u003cbutton class=\"dialog-close\" type=\"button\" aria-label=\"Schließen\">×\u003c/button>\u003cdiv class=\"editor-content\">\u003cp class=\"eyebrow\">EUER KLEINES DESIGNATELIER\u003c/p>\u003ch2>Eine Einladung, die nach euch aussieht.\u003c/h2>\u003cp class=\"editor-note\">Änderungen bleiben in dieser Vorschau. Mit „HTML speichern“ bekommt ihr eine vollständige Einladung inklusive eurer Bilder – kostenlos und ohne Konto.\u003c/p>\u003cform id=\"editor-form\">\u003clabel>Vorname 1\u003cinput name=\"name1\" required>\u003c/label>\u003clabel>Vorname 2\u003cinput name=\"name2\" required>\u003c/label>\u003clabel>Hochzeitsdatum\u003cinput name=\"date\" type=\"date\" required>\u003c/label>\u003clabel>E-Mail für Rückmeldungen\u003cinput name=\"email\" type=\"email\" placeholder=\"Optional · eure echte Kontaktadresse\">\u003c/label>\u003cdiv id=\"image-inputs\">\u003c/div>\u003cbutton class=\"primary-button\" type=\"submit\">Vorschau aktualisieren ↗\u003c/button>\u003c/form>\u003cbutton class=\"text-button\" id=\"export-html\">HTML mit Bildern speichern ↗\u003c/button>\u003cp class=\"editor-note\">Alle weiteren Texte und Uhrzeiten könnt ihr in wedding-config.js bearbeiten. Bilddateien verlassen euren Browser erst, wenn ihr die gespeicherte Einladung selbst teilt.\u003c/p>\u003c/div>';\n    document.body.append(dialog);dialog.querySelector('.dialog-close').onclick=()=>dialog.close();\n    dialog.addEventListener('close',()=>button.focus());button.onclick=()=>openDialog(dialog,button);\n    const form=dialog.querySelector('form');form.elements.name1.value=config.names[0];form.elements.name2.value=config.names[1];form.elements.date.value=config.date;form.elements.email.value=config.rsvpEmail;\n    const labels={couple:'Euer Paarfoto',hands:'Eure Hände / der Ring',church:'Kirchenillustration',party:'Mago-Illustration oder Foto'};\n    Object.entries(labels).forEach(([key,label])=>{\n      const wrap=document.createElement('label');wrap.className='image-input';wrap.textContent=label;\n      const input=document.createElement('input');input.type='file';input.accept='image/jpeg,image/png,image/webp';\n      const status=document.createElement('small');status.textContent='JPG, PNG oder WebP · bis 12 MB';wrap.append(input,status);$('#image-inputs').append(wrap);\n      input.onchange=()=>{const file=input.files[0];if(!file)return;if(file.size>12*1024*1024){status.textContent='Bitte eine Datei unter 12 MB wählen.';input.value='';return;}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){status.textContent='Bitte JPG, PNG oder WebP wählen.';return;}const reader=new FileReader();reader.onload=()=>{config.photos[key]=String(reader.result);$$('[data-photo=\"'+key+'\"]').forEach(loadPhoto);status.textContent=file.name+' · eingebunden';};reader.readAsDataURL(file);};\n    });\n    function applyEditorConfig(){if(!form.reportValidity())return false;const names=[form.elements.name1.value.trim(),form.elements.name2.value.trim()];if(names.some(name=>!name))return false;config.names=names;config.date=form.elements.date.value;const date=new Date(config.date+'T12:00:00Z');config.dateLabel=new Intl.DateTimeFormat('de-DE',{day:'numeric',month:'long',year:'numeric',timeZone:'UTC'}).format(date);config.weekday=new Intl.DateTimeFormat('de-DE',{weekday:'long',timeZone:'UTC'}).format(date);config.rsvpEmail=form.elements.email.value.trim();render();return true;}\n    form.onsubmit=event=>{event.preventDefault();if(applyEditorConfig())dialog.close();};\n    let templateLoading;\n    $('#export-html').onclick=async()=>{\n      if(!applyEditorConfig())return;\n      // The large self-contained export is loaded only when it is requested.\n      if(!window.INVITATION_TEMPLATE && !$('#wedding-config')) {\n        const button=$('#export-html'); button.disabled=true; button.textContent='Einladung wird vorbereitet …';\n        try {\n          if(!templateLoading) templateLoading=new Promise((resolve,reject)=>{\n            const script=document.createElement('script'); script.src='export-template.js';\n            script.onload=resolve; script.onerror=()=>{templateLoading=null;script.remove();reject(new Error('Exportvorlage nicht geladen'));}; document.head.append(script);\n          });\n          await templateLoading;\n        } catch(error) { button.textContent='Bitte erneut versuchen · HTML speichern'; button.disabled=false; return; }\n        button.disabled=false; button.textContent='HTML mit Bildern speichern ↗';\n      }\n      const exportConfig={...config,photos:{...config.photos}};\n      Object.entries(exportConfig.photos).forEach(([key,src])=>{exportConfig.photos[key]=window.INVITATION_PHOTOS?.[src] || src;});\n      const json=JSON.stringify(exportConfig,null,2).replace(/\u003c/g,'\\\\u003c');\n      const script='\u003cscript id=\"wedding-config\">window.WEDDING = '+json+';\u003c\\/script>';\n      const source=window.INVITATION_TEMPLATE || originalHTML;\n      const html=source.replace(/\u003cscript id=\"wedding-config\">[\\s\\S]*?\u003c\\/script>/,()=>script);\n      download(html,'text/html;charset=utf-8','Unsere-Hochzeit.html');\n    };\n  }\n  render();setInterval(updateCountdown,30000);if(editMode)setupEditor();\n})();\n\u003c/script>\n\u003c/body>\n\u003c/html>\n";
Object.entries({"__INVITATION_PHOTO_0__": "assets/images/paar.jpg", "__INVITATION_PHOTO_1__": "assets/images/haende.jpg", "__INVITATION_PHOTO_2__": "assets/loom/church-edition.webp", "__INVITATION_PHOTO_3__": "assets/loom/mago-flow.webp"}).forEach(([token,path]) => { window.INVITATION_TEMPLATE = window.INVITATION_TEMPLATE.replaceAll(token, window.INVITATION_PHOTOS[path]); });
